def solve():
    solutions = []
    for p in [3, 5, 7, 11]:
        for a in range(1, 100):
            for b in range(a, 200):
                # a^{p-1} + b = p^x
                val1 = a**(p-1) + b
                # Check if val1 is a power of p
                if val1 > 0 and val1 % p == 0:
                    temp1 = val1
                    while temp1 % p == 0:
                        temp1 //= p
                    if temp1 == 1:
                        # Now check b^{p-1} + a = p^y
                        val2 = b**(p-1) + a
                        if val2 > 0 and val2 % p == 0:
                            temp2 = val2
                            while temp2 % p == 0:
                                temp2 //= p
                            if temp2 == 1:
                                solutions.append((p, a, b))
    return solutions

print(solve())

def solve_extended():
    solutions = []
    for p in [3, 5, 7, 11, 13]:
        # Optimization: a^{p-1} + b = p^x.
        # b = p^x - a^{p-1}.
        # Since b >= a, p^x - a^{p-1} >= a.
        # Since a < b, p^x - a^{p-1} > a, so p^x > a^{p-1} + a.
        # Also b^{p-1} + a = p^y.
        for a in range(1, 200):
            # Let's try some values of x
            for x in range(1, 15):
                b = p**x - a**(p-1)
                if b >= a and b > 0:
                    val2 = b**(p-1) + a
                    # Check if val2 is a power of p
                    if val2 > 0 and val2 % p == 0:
                        temp2 = val2
                        while temp2 % p == 0:
                            temp2 //= p
                        if temp2 == 1:
                            solutions.append((p, a, b))
    return solutions

print(solve_extended())

def solve_large():
    solutions = []
    # Let's check more a values and higher powers
    for p in [3, 5, 7, 11, 13, 17, 19]:
        for a in range(1, 500):
            # b = p^x - a^{p-1}. Since b >= a, p^x >= a^{p-1} + a.
            # x >= log_p(a^{p-1} + a).
            min_x = (a**(p-1) + a)
            if min_x > 1:
                # We can estimate x
                # x_min = ceil(log_p(min_x))
                import math
                x_min = math.ceil(math.log(min_x, p))
            else:
                x_min = 1

            for x in range(x_min, x_min + 10):
                b = p**x - a**(p-1)
                if b < a: continue
                val2 = b**(p-1) + a
                # Check if val2 is a power of p
                if val2 > 0 and val2 % p == 0:
                    temp2 = val2
                    while temp2 % p == 0:
                        temp2 //= p
                    if temp2 == 1:
                        solutions.append((p, a, b))
    return solutions

print(solve_large())

def solve_final():
    solutions = []
    for p in [3, 5, 7, 11, 13, 17, 19]:
        # We want p^y <= b^{p-1} + b and b^{p-1} < p^y.
        # This means b is the largest integer such that b^{p-1} < p^y.
        # b = floor((p^y - 1)**(1/(p-1)))
        # Then a = p^y - b^{p-1}.
        # Check a <= b and a^{p-1} + b is a power of p.
        for y in range(1, 100):
            py = p**y
            # Calculate b = floor((p^y - 1)^(1/(p-1)))
            # Use float to estimate b, then check around it for safety.
            b_est = int((py - 1)**(1/(p-1)))
            for b in range(max(1, b_est - 2), b_est + 3):
                if b**(p-1) < py:
                    a = py - b**(p-1)
                    if 1 <= a <= b:
                        val = a**(p-1) + b
                        # Check if val is a power of p
                        if val > 0 and val % p == 0:
                            temp = val
                            while temp % p == 0:
                                temp //= p
                            if temp == 1:
                                solutions.append((p, a, b))
    return solutions

print(solve_final())
